// N5.10 hotfix: the MCP_TOOLS registry, extracted from transport.ts as a PURE-DATA
// module (zero imports). Two reasons: (1) transport.ts's transitive handler graph pulls
// jsr:@supabase/supabase-js, which the test environment cannot fetch (jsr-403) — so the
// registry literal was untestable in place, and an unescaped apostrophe in a tool
// description shipped as a syntax error that killed the edge function at boot (every
// MCP client connection dropped); (2) a dependency-free module lets the suite import
// and shape-check every tool entry. transport.ts re-exports it, so index.ts and all
// existing importers are unchanged.

export const MCP_TOOLS = [
  { name: 'list_projects', description: 'List the projects this account owns and the ones it holds a seat on (role per project: owner | maintainer | contributor | viewer). Call this first to get a project_id before using other project-scoped tools.', inputSchema: { type: 'object', properties: {}, required: [] }, requiredScope: 'read' },
  { name: 'search_catalog', description: 'Search NodeSpec\'s curated catalog of node ROLES (~120 architectural jobs) and TECHNOLOGIES (frameworks, databases, engines, PaaS/IaaS services, external APIs). ALWAYS search here BEFORE proposing nodes for technologies or roles you are not certain exist in this project\'s vocabulary — propose_patches validates against this catalog, and searching first yields exact ids plus per-entry guidance (when_to_use, how the thing is delivered: built / managed / called / configured-engine). Weighted full-text search; returns compact ranked results whose ENUMS are authoritative (treatment: leaf|boundary|container · ownership: build|rent|call|host · configMode) — reason and propose with the enums and ids; the description field is a human gloss, never a category.', inputSchema: { type: 'object', properties: { query: { type: 'string', description: 'What you are looking for — a technology name ("apache nifi", "aws s3"), a capability ("workflow automation", "vector database"), or a role ("message queue")' }, max_results: { type: 'number', description: 'Max results per section (default 10, max 25)' } }, required: ['query'] }, requiredScope: 'read' },
  { name: 'lookup_catalog', description: 'Fetch full catalog detail for one role, technology, or palette category: purpose, best practices, anti-patterns, config templates, suggested files, common connections. Use after search_catalog to pull implementation guidance for a specific entry before proposing or generating against it.', inputSchema: { type: 'object', properties: { role_id: { type: 'string', description: 'A node role id (e.g. "backend-service")' }, technology_id: { type: 'string', description: 'A technology id (e.g. "n8n", "aws-s3")' }, category: { type: 'string', description: 'A palette category name to list its roles' } }, required: [] }, requiredScope: 'read' },
  { name: 'get_project_context', description: 'Get assembled context for a node, feature, or requirement. Four views: brief (default) returns the build brief (promptDocument) + process hints; structured returns the machine-readable model context (specification, architecture, contracts with schemas as schemaPresent/schemaPreview/schemaHash, existing artifacts) with NO prompt document; full returns the structured context with complete schema bodies plus the prompt document exactly once; slice (nodes only) returns the node\'s own slice: every edge separately with its full contract, name and schema hash one hop past its upstream neighbours, what consumers\' criteria expect of it, only its mapped requirements with criteria state, tasks and tests with state and commit, leases on it and its neighbours, the constraints and vision sentences that apply, and its memory (decisions, changes, hand-offs, its learning, proofs at a commit, each with who and commit, flagged for review when its context changed after them). Every slice reports its size beside the whole spec\'s and what it left out; pass budget (approximate tokens) to trim it, and pass the fingerprint of an earlier slice as since to get only what changed. A node\'s vision is the sentences its outcomes cite, not the whole vision. This is MODEL TRUTH; the per-node BUILD DIRECTIVE is the task doc from generate_task_docs. Requirement targets report stored test-plan STATE only; get_test_plan returns (and generates) the plan itself.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, target_type: { type: 'string', enum: ['node', 'feature', 'artifact', 'requirement'], description: 'Type of target' }, target_id: { type: 'string', description: 'ID or label of the target' }, view: { type: 'string', enum: ['brief', 'structured', 'full', 'slice'], description: "Response shape: 'brief' (default) = promptDocument + hints; 'structured' = model context, schemas as presence/preview/hash; 'full' = everything, document once; 'slice' = the node's own measured slice." }, budget: { type: 'number', description: "view 'slice' only: approximate tokens for the whole answer (100 or more). Cuts run lowest value first and each is named in leftOut." }, since: { type: 'string', description: "view 'slice' only: the fingerprint an earlier slice answered with; only the sections that changed come back." } }, required: ['project_id', 'target_type', 'target_id'] }, requiredScope: 'read' },
  { name: 'propose_patches', description: `Submit changes for the user's review as ONE proposal. Say what you want with intents[] (the server writes the patches, mints the ids, answers with them) or with patches[]; a call needs one, both may ride together. Validation runs first and names the field or intent it refused.
INTENTS: { kind: 'add_node', label, type, technology? } | { kind: 'connect_nodes', source|sourceLabel, target|targetLabel, contract: { kind, name } | { id } } | explode_node { nodeId, parts: [{ label, role, files, why, takes? }] } (split_node is its alias) | collapse_node { nodeId } | set_contract_schema { contractId, schema } | bind_file { path, nodeId, artifactKind?, artifactId? } (a file in the repository to a node; artifactId moves one already bound) | place_on_step { candidateId, stepIds }. place_on_step, the workflow ops (upsert_workflow, upsert_workflow_step, set_outcome_step_maps, delete_workflow*) and the constraint ops (create_constraint, update_constraint, delete_constraint) need Indie and above; below it the call is refused naming them, and create_candidate files the outcome on the project. An add_node may take ref: "svc" and a later intent in the call names that node "@svc" (source, target, parentId, nodeId). Any intent may cite evidence: [{ path, line?, note? }], shown to the reviewer. explode_node and collapse_node need the node's lease (checkout_task level node); each part's role is one the node's role lists (lookup_catalog), every file goes to one part or stays, and the files' imports become the edges between parts. A database explodes into groups (part-table-group): each lists its tables { name, columns?, keys?, kind?, file? (the file that defines it, wherever it lives) } and references { part, via: foreign_key | code }, and a take of a service's edge says access: read | write | both, as that service's queries use the group.
A WHOLE CALL: {"project_id":"acme","intents":[{"kind":"add_node","label":"Web","type":"frontend","technology":"react"},{"kind":"connect_nodes","sourceLabel":"Web","targetLabel":"Orders","contract":{"kind":"rest","name":"Orders API"}}]}
Node type is a catalog ROLE id and technology a catalog TECHNOLOGY id: use what search_catalog returns, never an invented id.
PATCHES: { type, payload }, your own uuids: add_node, add_contract (kind: rest, graphql, grpc, websocket, sse, kafka, amqp, sql, nosql, ipc, dependency, custom), add_edge (contractId required), add_artifact (content, or content_ref), update_* { id, changes }, remove_* { id }; spec ops ride the batch, among them create_constraint { ctype: technology|architecture|deployment|performance|security|compliance|cost|other, description, title?, rationale?, scope?: { kind: role|technology|contract_kind|node, value }, kind?: guide|check, check?: { predicate: contract_has_schema | no_calls_between_roles { from, to } | technology_in_list { technologies } | sync_calls_at_most { max }, severity: warn|refuse, params } } for a standing condition the build must honour, in the user's words (NodeSpec ships none); update_constraint { constraintId, changes?, addWaiver?: { target, reason, expiresAt? }, removeWaiver? } and delete_constraint { constraintId, reason } are accepted by the user in the app only. A batch that adds a break of a refusing check is refused; of a warning check, it files with the warning; create_candidate and update_candidate take serves, the vision sentences the outcome serves (ids from get_outcome_board, or the words). Contracts and nodes before the edges naming them, parents before children. A node sits only in a parent that may hold it, as on the canvas: get_project_context on the parent (or lookup_catalog on its type) says what it may hold, a batch breaking that is refused naming it, and placementKind follows how the parent holds (hosts, contains or scopes), so leave it unset.
OPTIONS: base_sequence (an overtaken batch is refused, naming the patches); content_ref (a pushed commit sha); expected_patch_count (a short delivery is refused); finalize/proposal_id for chunked sessions, 500 patches per call.
ONE PLANE PER CALL: canvas ops and spec ops (requirements, outcomes, workflows, constraints) are refused together. A batch on either plane applies as it files when every lane it touches is at Auto and your key may write (routed: applied); a promotion, a settle, a changed or retired constraint, or a confirmed requirement still waits, and the routing note says why. A proposal on something a waiting proposal already changes is refused: wait for that one, then re-read.
Field lists, a patches example, derivation rules: docs/WORK_LOOP_PLAN.md Phase C5.`, inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, intents: { type: 'array', items: { type: 'object' }, description: 'Optional. Structured intents compiled server-side into patches before validation: { kind: add_node | connect_nodes | explode_node | collapse_node | bind_file | set_contract_schema | place_on_step, ...fields, evidence? }. The response lists the ids each intent minted; the proposal records the intents so the user sees what you want, not the patches.' }, patches: { type: 'array', items: { type: 'object', properties: { type: { type: 'string', description: 'Patch operation type: add_node, update_node, remove_node, add_edge, update_edge, remove_edge, add_contract, update_contract, add_artifact, update_artifact, and related ops.' }, payload: { type: 'object', description: 'Operation payload for the given type; see the PATCH REFERENCE in the tool description for required fields per op and the closed enum values for kind fields.' }, metadata: { type: 'object', description: 'Optional. { summary, actorType (human|ai|system), preconditions }. id/timestamp are generated server-side if omitted. preconditions ([{type: hash_match|value_exists|value_equals, path, expected?}]) guard spec-plane patches (update_requirement / delete_requirement / update_candidate) against rows that changed since you read them, re-checked against the CURRENT row when the proposal is accepted; a stale row fails that patch loudly, naming the path and current state.' } }, required: ['type', 'payload'] }, description: 'NodeSpec patch operations, ordered so referenced entities (contracts, nodes, parents) come before the patches that reference them. Optional when intents[] carries the change: a call needs intents, patches, or both.' }, explanations: { type: 'array', items: { type: 'string' }, description: 'Explanations for each patch' }, external_agent: { type: 'string', description: 'Identifier for the external agent (e.g., claude-code)' }, content_ref: { type: 'string', description: 'Git ref: the pushed commit sha (preferred; pins the bytes) or a branch name. Every add_artifact in this call that omits content becomes bindings-only: its file body is pulled from git at this ref when the user accepts. Requires the project to have a git integration; push the commit BEFORE the user accepts or the accept fails with the missing paths.' }, proposal_id: { type: 'string', description: 'Chunked sessions: the session id returned by a finalize:false call; this call APPENDS its patches to that staged session instead of creating a new proposal. The session must sit on the same branch_id.' }, finalize: { type: 'boolean', description: 'Chunked sessions: false STARTS a staged session (invisible to review); true on a call with proposal_id promotes the whole session to ONE pending proposal (patches optional on that call). Omit for the default single-call behavior.' }, base_sequence: { type: 'number', description: 'Optional. The headSequence you last read from get_architecture_overview; a batch whose targets a later patch changed is refused, naming them.' }, expected_patch_count: { type: 'number', description: 'Truncation guard: the number of patches you INTENDED this call to carry. If fewer arrive, the call fails loudly with both numbers instead of creating a fragment. Recommended on every call with more than ~20 patches.' } }, required: ['project_id'] }, requiredScope: 'propose' },
  { name: 'get_proposal_status', description: 'Check if patches were accepted/rejected and get detailed status This is the status of a change YOU proposed. A decided proposal carries the reviewer\'s reviewNote when they left one, with reviewNoteAsk: a note that states a standing rule for the project can be filed as a constraint, the user deciding. An inbound git commit is a change card, read with get_pending_changes.', inputSchema: { type: 'object', properties: { proposal_id: { type: 'string', description: 'The proposal UUID returned from propose_patches' } }, required: ['proposal_id'] }, requiredScope: 'read' },
  { name: 'generate_task_docs', description: 'Generate each node\'s task document (.nodespec/tasks/*.task.md) on the server, deterministically, and file them as one pending proposal: the mapped requirements with their criteria as scoped task boxes, the node\'s contracts, technology context, an ordered Implementation Tasks checklist of work orders with [PLACEHOLDER: schema|owner|dependency|config] tags where the model has gaps, and an AI-authored Implementation Context section that survives regeneration. Use this instead of hand-writing task docs with add_artifact. Call after architecture and requirement mappings exist; node_ids scopes it. A context fingerprint refreshes each doc at git push when requirements or architecture change. After acceptance, write each work order\'s steps under its task line as indented "  - [ ] step" lines (update_artifact with base_sequence; keep task ids, criterion citations and placeholders); they stay with it through regeneration, and the response lists workOrdersWithoutSteps, stepsToReview and stepFormat. A node is never complete while a placeholder remains. A node another agent holds (checkout_task: the node, or task or code work in it), or whose document a waiting proposal already changes, keeps its document as it is and comes back under held with who; the rest are generated. The proposal records the graph it was generated from: if a document or its node changes before it is accepted, the accept applies nothing, and you generate again. Doctrine: docs/WORK_LOOP_PLAN.md Phase C5.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, node_ids: { type: 'array', items: { type: 'string' }, description: 'Optional: limit generation to these nodes (UUIDs or exact labels). Omit to cover every leaf node.' }, external_agent: { type: 'string', description: 'Identifier for the requesting agent' } }, required: ['project_id'] }, requiredScope: 'propose' },
  { name: 'create_api_key', description: 'Connect a new agent: mint the API key it authenticates with (X-MCP-API-Key). Requires JWT auth, the signed-in person; a key never mints a sibling. Keys default to read + write + propose. The plan caps how many agents one person keeps connected at once (community one, Indie and above five per person, keys and OAuth clients alike) and one live key per name; a refusal names the cap or the taken name. One key per agent: a key serves the connection that initialized with it last, and a call from any other connection on it is refused naming that one.', inputSchema: { type: 'object', properties: { name: { type: 'string', description: 'The agent this key belongs to, as the lease board will show it (one live key per name)' }, scopes: { type: 'array', items: { type: 'string', enum: ['read', 'write', 'propose'] }, description: 'Permissions for this key.' }, expires_in_days: { type: 'number', description: 'Number of days until expiration.' } }, required: ['name'] }, requiredScope: null },
  { name: 'list_api_keys', description: 'The signed-in person\'s connected agents: API keys and OAuth-connected clients, with the plan\'s allowance (connections.active of connections.limit). Requires JWT auth.', inputSchema: { type: 'object', properties: {}, required: [] }, requiredScope: null },
  { name: 'revoke_api_key', description: 'Disconnect an agent: an API key by key_id, or an OAuth-connected client by client_id. The credential stops working and the live leases it held are released. Requires JWT auth.', inputSchema: { type: 'object', properties: { key_id: { type: 'string', description: 'The API key UUID to revoke' }, client_id: { type: 'string', description: 'The OAuth client id to disconnect instead of a key' } }, required: [] }, requiredScope: null },
  { name: 'relate_requirements', description: 'Record or remove an AUTHORED requirement↔requirement relation: \'expands\' (this requirement extends an earlier one — renders as a lineage badge on the card and an edge in the decomposition view), \'depends_on\', or \'relates_to\'. NodeSpec NEVER writes relations on its own — you or the user do; architectural coupling via shared/adjacent nodes is DERIVED automatically and read from list_requirements\' coupling field, so only record relations that carry intent (lineage, ordering, grouping). Both requirement refs accept REQ-NNN or the row uuid. Adding an existing relation is a no-op (alreadyExists:true). Prefer recording \'expands\' lineage AT creation via create_requirement\'s relations parameter. AUTONOMY ROUTING: this tool consults the project\'s per-lane automation policy — at \'Ask first\' the call is refused (discuss with the user); at \'Propose\' nothing is changed and the call files a pending proposal instead (response carries routed: proposed + proposalId; the user accepts in the approvals queue or via resolve_proposal); at \'Auto-apply\' (the shipped default, today\'s behavior) it applies and records a merged proposal row as audit. Requirement to REQUIREMENT only; binding a requirement to the nodes that serve it is map_requirement.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, from_requirement_id: { type: 'string', description: 'The relating requirement (REQ-NNN or uuid) — for \'expands\', the NEW requirement' }, to_requirement_id: { type: 'string', description: 'The related requirement — for \'expands\', the older one being extended' }, relation_type: { type: 'string', enum: ['expands', 'depends_on', 'relates_to'] }, mode: { type: 'string', enum: ['add', 'remove'], description: "Default 'add'. 'remove' deletes the exact (from, to, type) fact." }, notes: { type: 'string', description: 'Optional context for the relation' } }, required: ['project_id', 'from_requirement_id', 'to_requirement_id', 'relation_type'] }, requiredScope: 'write' },
  { name: 'update_vision', description: 'Set the project vision — the anchoring statement every task packet embeds. The vision belongs to the USER: greenfield, ASK them for it in their words and record it here BEFORE drafting requirements; brownfield (after a repo import), draft it FROM the imported graph and present it for their edit before setting it. Creates a minimal specification if the project has none. Refuses blank visions. AUTONOMY ROUTING: this tool consults the project\'s per-lane automation policy — at \'Ask first\' the call is refused (discuss with the user); at \'Propose\' nothing is changed and the call files a pending proposal instead (response carries routed: proposed + proposalId; the user accepts in the approvals queue or via resolve_proposal); at \'Auto-apply\' (the shipped default, today\'s behavior) it applies and records a merged proposal row as audit.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, vision: { type: 'string', description: "The vision text (the user's words, or your user-approved draft). Max 10000 chars." } }, required: ['project_id', 'vision'] }, requiredScope: 'write' },
  { name: 'get_node_context', description: 'What an IMPORTED node holds, from the repo index, with no file reading and no context stuffing. Returns file/language/role counts, the hub files (most depended-on, by PageRank) with artifact ids and git refs, a signals rollup (declared routes, outbound HTTP client libraries, manifest dependencies, top imports, deployment surfaces), dependencies in and out of the node with sample file-pair evidence, and the summary the import wrote. NodeSpec calls no model: read the hub files yourself to say what the component does. Use it to write a brief or answer "what does this component do?" for a repository NodeSpec imported; combine with search_repo_index to locate a specific route, symbol or file inside the node. The index exists once an import is ACCEPTED; before that the response names the steer. TIER: available on Indie and above; a Community-tier account gets a refusal that names the upgrade path.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, node_id: { type: 'string', description: 'The node UUID or its exact label' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, hub_limit: { type: 'number', description: 'Hub files to return (default 12, max 50)' } }, required: ['project_id', 'node_id'] }, requiredScope: 'read' },
  { name: 'search_repo_index', description: 'Find files in an IMPORTED repository by path, route text or import text: trigram + full-text over the repo index, bounded, every hit attributed to its node. Ask "where is the Stripe webhook?", "which file declares /predict?", "OrdersController" and get paths with node labels, centrality and matched routes; scope with node_id to search inside one component. Never ask the user for the repository: this replaces reading files. TIER: available on Indie and above; a Community-tier account gets a refusal that names the upgrade path.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, query: { type: 'string', description: 'Path fragment, route, symbol or words (at least 2 characters)' }, node_id: { type: 'string', description: 'Optional node UUID or label to search inside' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, max_results: { type: 'number', description: 'Max results (default 20, max 100)' } }, required: ['project_id', 'query'] }, requiredScope: 'read' },
  { name: 'get_import_context', description: 'The CONTEXT BACKFILL read for a brownfield project (V3 9.6): after a repository import, the repo\'s READMEs (root first, then by depth, monorepo-aware), package descriptors (package.json / pyproject / Cargo.toml / go.mod / pom.xml name + description), docs index pages, CI workflow and job names, and e2e spec titles in file order, each bounded in bytes, every user-authored string inside the untrusted-data envelope, with a doctrine block outside it. It also answers what the user is here to do (intent): the changes they opened in the app, each with the nodes in its scope and the existing test files on them, or the question to ask (migrate it, harden it, change a component, extend it, describe the whole system). Read it, then DRAFT the vision (from descriptors, CONFIRMED by the user in their own words, never written from code). A change is upsert_workflow {name, intent} with template steps; its outcomes go on its steps (create_candidate {workflowName, stepName, serves}) and its constraints are create_constraint {workflowName}. Describing the whole system drafts lanes from the CI jobs and e2e order instead. File it as ONE propose_patches call; it lands under Agents, Proposals in the app. Workflows and outcomes are proposed, never applied. TIER: available on Indie and above: a Community-tier account gets a refusal that names the upgrade path.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch; the latest import on that branch is read.' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'backfill_requirements', description: 'The deterministic half of the post-import spec backfill. Without accept/dismiss it derives requirement CANDIDATES from the repo index: one "<Resource> API" per declared route group with a criterion per route, one "<Node> data model" per node owning schema/migration/model files, and one "<Module> behaviour" per test file whose test titles could be read (bounded fetch at the indexed sha): and STAGES them for review; it never writes a requirement on its own. Re-running is idempotent (pending candidates refresh, decided ones are untouched). Review the pending list WITH THE USER, then call again with accept: [candidate ids] and/or dismiss: [ids]: accepted candidates become requirements through the normal create path (source ai-generated, unconfirmed, every criterion UNMET: existing code proves nothing until tested) mapped to their node at confidence 0.6; dismissed ones stay out of later runs. uncoveredNodes lists imported nodes the index found no evidence for: write those with create_requirement + map_requirement. While a change is open it runs per node (node_id, a node the change touches) and refuses a whole-system run unless whole_system is true. Ask the user for the vision first (update_vision) when the project has none. TIER: available on Indie and above: a Community-tier account gets a refusal that names the upgrade path.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, node_id: { type: 'string', description: 'Optional node UUID or exact label to generate candidates for one imported node only' }, whole_system: { type: 'boolean', description: 'Run across every imported node while a change is open (the user asked for the whole system). Default false.' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, accept: { type: 'array', items: { type: 'string' }, description: 'Candidate ids (from a previous response) to turn into requirements + mappings' }, dismiss: { type: 'array', items: { type: 'string' }, description: 'Candidate ids to mark dismissed (never regenerated)' } }, required: ['project_id'] }, requiredScope: 'write' },
  { name: 'run_repo_import', description: 'THE repository-import tool — one tool, end to end. First call: starts the deterministic pipeline (skeleton scan → archive fetch → import resolution → per-group analysis → synthesis), which then DRIVES ITSELF stage by stage in the background; a running response carries progress and means poll again in about 30 seconds (a stalled job is re-kicked automatically; completed work replays instantly). When the draft stages, the SAME response carries everything needed to finalize: per-group frames with evidence, the draft nodes/edges/contracts, per-node signals (declared routes, outbound HTTP clients, manifest deps, top imports — the evidence for add_edges), the open questions the pipeline refused to guess, and the import doctrine. Second call: pass a decisions object — {approve: true} to promote the draft unchanged, or bounded revisions applied server-side (renames, role_changes validated against the live catalog, drop_nodes, add_edges with citable evidence, drop_edges). Promotion makes ONE proposal appear in the app for the user to review and apply. After acceptance, calling again reports backfill coverage (nodes still missing requirements). Refused when the repo carries a .nodespec/model.json anchor (authored designs are adopted, never re-inferred) or when the canvas already has nodes — pass restart=true only after a failure or when the user explicitly wants a fresh re-analysis. TIER: available on Indie and above — a Community-tier account gets a refusal that names the upgrade path (gitops file assignment via propose_patches stays available on every tier).', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, restart: { type: 'boolean', description: 'Start a fresh import after a failure, or when the user explicitly wants re-analysis over an existing canvas/accepted import.' }, decisions: { type: 'object', description: 'Your finalization verdict on the staged draft. Either approve:true, or any combination of the revision arrays.', properties: { approve: { type: 'boolean' }, renames: { type: 'array', items: { type: 'object', properties: { from_label: { type: 'string' }, to_label: { type: 'string' } }, required: ['from_label', 'to_label'] } }, role_changes: { type: 'array', items: { type: 'object', properties: { label: { type: 'string' }, role_id: { type: 'string' } }, required: ['label', 'role_id'] } }, set_technology: { type: 'array', items: { type: 'object', properties: { label: { type: 'string' }, technology: { type: 'string' } }, required: ['label', 'technology'] } }, drop_nodes: { type: 'array', items: { type: 'string' } }, add_edges: { type: 'array', items: { type: 'object', properties: { from_label: { type: 'string' }, to_label: { type: 'string' }, contract_kind: { type: 'string' }, label: { type: 'string' }, evidence: { type: 'string' } }, required: ['from_label', 'to_label', 'evidence'] } }, drop_edges: { type: 'array', items: { type: 'object', properties: { from_label: { type: 'string' }, to_label: { type: 'string' } }, required: ['from_label', 'to_label'] } } } } }, required: ['project_id'] }, requiredScope: 'propose' },
  { name: 'get_build_readiness', description: 'Build preflight; call before implementing any node. Reports blocking gaps (contracts with no schema or a broken schemaRef, criteria whose owning node is unresolved, missing or stale task documents) and advisories (no recorded configuration, no mapped requirements, failing or stale test cases, candidatesOpen), a remediations map (one action per gap kind), a dependency-ordered buildOrder, and the chain (AA.1): a project-level block whose blockers are vision (none, or no outcome cites it), off-vision (an outcome cites no sentence of the current vision), origin (a requirement derives from no outcome) and, on plans with Workflows, no-step; unserved sentences are advisory and constraints are only ever a note. Broken checks are constraint advisories; unscoped reads add constraintSignals. Nothing else waits on the chain: close its gaps alongside the build. Two steps: unscoped answers summary rows per node ({ ready, blockerCounts, advisoryCounts }); re-call with node_ids (detail defaults to \'full\') for gap objects, where schema gaps carry draftInputs (selfTechnology, counterpartyTechnology, apiEndpoints, servingCriteria, suggestedSpecFormat). You draft the missing schemas and submit one propose_patches batch of update_contract patches; ownership gaps settle via map_requirement, docs via generate_task_docs, the test backlog via get_test_plan and report_test_results; then re-check and implement in buildOrder. Doctrine: docs/WORK_LOOP_PLAN.md Phase C5.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, node_ids: { type: 'array', items: { type: 'string' }, description: 'Optional: limit the check to these nodes (UUIDs or exact labels). Omit to check every leaf node.' }, detail: { type: 'string', enum: ['summary', 'full'], description: "Row shape override. 'summary' (default when unscoped): per-node ready + gap counts by kind. 'full' (default when node_ids given): every gap with detail, relatedNodeIds, and draftInputs." } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'get_pending_changes', description: 'The pending external git changes the sync check found for a project, on the branch it reads (trackedBranch: commit and push there). Each card carries its changed files, commit info, status, authors (files grouped by commit author) and ticks: criterionDeltas (criteria ticked in task docs) and taskDeltas (task checkboxes), stamped criteriaApplied/ticksApplied once applied (see resolve_change). bindingResolution: files the push declared in .nodespec/bindings.json, resolved or flagged. Cards carry touchesHeldWork (R8) when someone else\'s commit changed files under another holder\'s exclusive lease (holder, credential, held ref, paths, by); resolve the change WITH the holder, never over them. heldWorkCollisions counts them. With change_event_id the answer is that card\'s reconcile packet: each file\'s owner (its binding, the repository index, or a suggested node with the reason) and kind (task doc, test, spec or model anchor); each touched node\'s role, contracts, requirements (locked, confirmed), tests, holds, task-doc freshness; structural signals from the diff (routes, outbound hosts, dependencies naming catalog entries, new directories with a manifest); what the change is (content-only, needs-binding, structural, spec, model-edited, conflicts); and a draft of intents citing file and line, to edit and pass to resolve_change. NOT a proposal: a change you proposed is read with get_proposal_status.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, change_event_id: { type: 'string', description: 'Optional. One card\'s changeEventId: answer its reconcile packet instead of the list.' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'resolve_change', description: 'Accept or dismiss a pending git change event. Optionally reconcile it when accepting, with patches (update_artifact, remove_artifact) or intents. Ticks from task docs (criterionDeltas, taskDeltas; see get_pending_changes) split by kind. A criterion tick is never applied by an agent: it stays on the card, which stays pending for a person to apply it in the Git panel (the response says waitingForPerson). A task tick follows the Tasks setting: Ask first refuses the accept, Propose leaves the ticks on the card for a person, Auto-apply marks those tasks done with git provenance when you pass apply_ticks: true with resolution "accepted". Ticks only ever apply on accept, never twice, and unticks in the file are never applied. Pass commit_sha as get_pending_changes returned it: a card that has since moved on to cover new commits is refused, so read it again. Patches and intents (as propose_patches: add_node with ref, connect_nodes, explode_node, bind_file, each citing evidence) are filed as ONE proposal and the change stays pending until a person accepts it; the last sync moves then. With the Architecture lane at Auto the proposal applies as it files and the change resolves with it. At Auto-apply, an accept of a change carrying task ticks without apply_ticks is refused. A change card is a git commit, never a proposal: to decide a proposal use resolve_proposal.', inputSchema: { type: 'object', properties: { change_event_id: { type: 'string', description: 'The change event UUID' }, commit_sha: { type: 'string', description: 'The card\'s commitSha as you read it from get_pending_changes' }, resolution: { type: 'string', enum: ['accepted', 'dismissed'], description: 'Whether to accept or dismiss the change' }, patches: { type: 'array', items: { type: 'object' }, description: 'Optional patches to apply when accepting. Supports update_artifact (for modified files) and remove_artifact (for deleted files) patch types.' }, intents: { type: 'array', items: { type: 'object' }, description: 'Optional intents, as propose_patches takes them (add_node with ref, connect_nodes, explode_node, bind_file { path, nodeId }), each may cite evidence: [{ path, line?, note? }]. Filed with any patches as ONE proposal.' }, apply_ticks: { type: 'boolean', description: 'With resolution "accepted" and the Tasks setting at Auto-apply: mark the change\'s ticked tasks done (git provenance). Criterion ticks are never applied by an agent. Refused when the change carries no deltas.' } }, required: ['change_event_id', 'commit_sha', 'resolution'] }, requiredScope: 'write' },
  { name: 'get_project_status', description: 'Get the current process flow status of a project including phase, counts, and what action to take next. phaseStatus is DERIVED from live progress (requirements, canvas architecture, reported test evidence) — never a stale stored snapshot; when the stored wizard column lags, storedPhaseStatus reports it alongside. Call this first to understand where the project is in the requirements -> architecture -> code pipeline and what to do next. Once the pipeline reaches the code phase, call get_build_readiness before implementing any node — it lists the blocking gaps (undefined contract schemas, unresolved criterion ownership, missing/stale task docs) with their resolution actions and the dependency-ordered build sequence. If the response shows hasVision:false, ask the USER for their vision — in their words — and set it via update_vision BEFORE drafting requirements: the vision anchors every task packet. The response\'s testBudget block is the TEST-BUDGET gauge: one binding test per acceptance criterion is the evidence contract (the smoke tier — "verified (smoke)" is a legitimate board state), deep-tier tests are deferred until a requirement\'s smoke tier is green, and overTested + nudge name the requirements whose case count exceeds the sprawl threshold — consolidate those instead of adding more.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'get_architecture_overview', description: 'Get the full architecture topology including all nodes, edges, contracts, container hierarchy, artifact completeness, and a Mermaid diagram. Use this to understand the complete system before zooming into specific nodes with get_project_context. Every answer carries headSequence (pass it to propose_patches as base_sequence); with since_sequence the answer also lists the patches appended after that read, the user\'s canvas edits included, so ask what changed since you last looked before proposing.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch if omitted.' }, since_sequence: { type: 'number', description: 'Optional. A headSequence this tool answered earlier; the answer lists what was appended after it (sequence, actorType, type, summary).' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'create_project', description: 'Create a new empty project (blank canvas, main branch). Free accounts are limited to two projects; the tool enforces this and returns an upgrade message when the limit is reached. Repo-import project creation is not available via MCP.', inputSchema: { type: 'object', properties: { name: { type: 'string', description: 'The project name (must be unique among your projects)' }, description: { type: 'string', description: 'Optional short project description' } }, required: ['name'] }, requiredScope: 'write' },
  { name: 'create_requirement', description: 'Create a requirement in a project specification. Auto-generates the next REQ-NNN id unless requirement_id is provided. Creates a minimal specification automatically if the project has none yet. Acceptance criteria accept plain strings or { text, verification } objects: verification \'automated\' (the default — plain strings mean automated) marks a criterion proven ONLY by report_test_results evidence; \'manual\' marks one proven ONLY by ticking its box in the owning node\'s task doc and having the user approve the change card — report_test_results refuses to bind manual criteria. Pass section to file the requirement under a named section (matched case-insensitively against the spec\'s existing sections, created when absent) — the same grouping the app\'s Spec view and Work Board render. If the project has no vision yet (get_project_status hasVision:false), ask the USER for it and record it via update_vision BEFORE drafting requirements — requirements drafted into a vacuum anchor to nothing. AUTONOMY ROUTING: this tool consults the project\'s per-lane automation policy — at \'Ask first\' the call is refused (discuss with the user); at \'Propose\' nothing is changed and the call files a pending proposal instead (response carries routed: proposed + proposalId; the user accepts in the approvals queue or via resolve_proposal); at \'Auto-apply\' (the shipped default, today\'s behavior) it applies and records a merged proposal row as audit.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, name: { type: 'string', description: 'Short requirement name' }, description: { type: 'string', description: 'Full requirement description' }, category: { type: 'string', description: 'One of: functional, non-functional, technical, business. Defaults to functional.' }, section: { type: 'string', description: "Optional section NAME to file the requirement under — matched case-insensitively against the spec's existing sections; a miss creates the section at the end of the order." }, acceptance_criteria: { type: 'array', items: { anyOf: [{ type: 'string' }, { type: 'object', properties: { text: { type: 'string', description: 'The criterion text' }, verification: { type: 'string', enum: ['automated', 'manual'], description: "Proof lane: 'automated' (default) = report_test_results evidence; 'manual' = task-doc tick + user approval" }, mark: { type: 'string', description: "7.3 (Government): a classification mark such as 'CUI' or 'CUI//SP-PRVCY' — only the owner and seats cleared for the exact mark see the item" } }, required: ['text'] }] }, description: 'Optional criteria — strings (automated) or { text, verification } objects' }, requirement_id: { type: 'string', description: 'Optional explicit id like REQ-042; auto-generated when omitted' }, relations: { type: 'array', items: { type: 'object', properties: { to: { type: 'string', description: 'Target requirement (REQ-NNN or row uuid)' }, type: { type: 'string', enum: ['expands', 'depends_on', 'relates_to'] }, notes: { type: 'string', description: 'Optional context' } }, required: ['to', 'type'] }, description: "Optional AUTHORED relations recorded at creation (source 'ai') — e.g. [{to:'REQ-007', type:'expands'}] when this requirement extends completed work. Unresolvable targets are reported back (relationsFailed), never fatal." } }, required: ['project_id', 'name', 'description'] }, requiredScope: 'write' },
  { name: 'update_requirement', description: 'Update fields on an existing requirement: name, description, category, status (read-only legacy), acceptance_criteria, section (a section NAME, matched case-insensitively and created when absent; null clears it), archived (true archives, false restores; a human act). Locked means locked: a locked requirement refuses every write; no tool unlocks, the user does in the app. Done is derived from evidence and never written. Replacing criteria carries met, testId, provenance and verification forward for entries whose text is unchanged; criteria accept strings or { text, verification: \'automated\' | \'manual\' } (a plain string keeps the lane; manual is proven by the task-doc tick and the user\'s approval, never by report_test_results). Routing: the Requirements lane\'s level decides (Ask first refuses; Propose files a proposal, routed: proposed + proposalId; Auto-apply applies and records a merged proposal), and a confirmed requirement always files as a proposal. preconditions: [{ type: value_equals | value_exists | hash_match, path, expected }] are checked against the current row before the write and again at accept; a stale row fails naming the path (value_equals on updated_at is the whole-row token). Doctrine: docs/WORK_LOOP_PLAN.md Phase C5.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, requirement_id: { type: 'string', description: 'Requirement id (REQ-xxx) or row UUID' }, preconditions: { type: 'array', items: { type: 'object', properties: { type: { type: 'string', enum: ['hash_match', 'value_exists', 'value_equals'], description: 'value_equals: exact-serialization equality with expected; value_exists: present and non-null; hash_match: expected is the sha256 hex of the current value (strings as-is, everything else JSON-serialized)' }, path: { type: 'string', description: "Dot path from the row, e.g. 'name', 'updated_at', 'acceptance_criteria.0.text'" }, expected: { description: 'The expected value (value_equals) or sha256 hex digest (hash_match); ignored for value_exists' }, mark: { type: 'string', description: "7.3 (Government): set a classification mark (e.g. 'CUI//SP-PRVCY'); null clears it" } }, required: ['type', 'path'] }, description: 'Optimistic-concurrency guards evaluated against the current requirement row before applying; any failure refuses the whole call with the path and current state' }, name: { type: 'string' }, description: { type: 'string' }, category: { type: 'string', description: 'functional | non-functional | technical | business' }, status: { type: 'string', description: 'LEGACY (9.8): read-only in the app; the derived ladder is the status. Accepted for old integrations: pending | in-progress | implemented | validated | blocked' }, archived: { type: 'boolean', description: 'true archives the requirement (the explicit archive, a human act); false restores it. Done is derived, never written.' }, section: { anyOf: [{ type: 'string' }, { type: 'null' }], description: "Section NAME to move the requirement to (matched case-insensitively, created when absent); null clears the section." }, acceptance_criteria: { type: 'array', items: { anyOf: [{ type: 'string' }, { type: 'object', properties: { text: { type: 'string', description: 'The criterion text' }, verification: { type: 'string', enum: ['automated', 'manual'], description: "Proof lane: 'automated' = report_test_results evidence; 'manual' = task-doc tick + user approval. Omit to keep the existing lane." } }, required: ['text'] }] }, description: 'Replaces the full acceptance criteria list (evidence + lane state carried forward by exact text match)' } }, required: ['project_id', 'requirement_id'] }, requiredScope: 'write' },
  { name: 'delete_requirement', description: 'Delete a requirement — the lane of LAST resort, for genuinely disposable drafts only. Refuses when the requirement is locked, and (unless force is true) when it is mapped to architecture elements OR carries test-case evidence — deletion CASCADES the test_cases rows, destroying recorded evidence. For anything with history, PREFER SUPERSESSION over deletion: create_requirement with relations [{to, type: \'expands\'}] records the lineage and archives the completed original off the working set (the board\'s archived lane), and update_test_case (retire: true) parks obsolete cases with their history intact. force: true cascades mappings AND evidence. AUTONOMY ROUTING: this tool consults the project\'s per-lane automation policy — at \'Ask first\' the call is refused (discuss with the user); at \'Propose\' nothing is changed and the call files a pending proposal instead (response carries routed: proposed + proposalId; the user accepts in the approvals queue or via resolve_proposal); at \'Auto-apply\' (the shipped default, today\'s behavior) it applies and records a merged proposal row as audit. MULTI-AGENT PRECONDITIONS: pass preconditions ({type: value_equals|value_exists|hash_match, path, expected}) to guard the delete against a row that changed since you read it — checked before the delete and again at accept time for proposals; failure names the path and current state.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, requirement_id: { type: 'string', description: 'Requirement id (REQ-xxx) or row UUID' }, preconditions: { type: 'array', items: { type: 'object', properties: { type: { type: 'string', enum: ['hash_match', 'value_exists', 'value_equals'] }, path: { type: 'string' }, expected: {} }, required: ['type', 'path'] }, description: 'Optimistic-concurrency guards evaluated against the current requirement row before deleting' }, force: { type: 'boolean', description: 'Also delete architecture mappings referencing this requirement' } }, required: ['project_id', 'requirement_id'] }, requiredScope: 'write' },
  { name: 'get_test_plan', description: 'The requirement\'s test plan (tests.md), generated on the server from the requirement, its criteria and the mapped nodes; no model. Plans follow schemas: scenarios on a schemaless contract render a [blocked by schema] marker and the response lists them in schemaBlockedContracts (resolve via get_build_readiness draftInputs and update_contract; the plan refreshes). Automated criteria are yours to implement and run, reported through report_test_results; verification: \'manual\' criteria sit in the Manual Verification checklist and are proven only by the task-doc tick and the user\'s approval. Under each test case heading, write the test\'s statements as "- [ ] Given ..., when ..., then ..." lines in the plan; they stay with their criterion when the plan regenerates. When the plan\'s inputs change (criteria, mappings, contract schemas) this call regenerates it, keeps your Test Strategy and statements, and files it as a proposal so the stored copy and git match. A stale case (requirement text edited, mappings changed, a bound file\'s content changed) must be re-run and reported. The response carries the plan and testPlanArtifactId, schemaBlockedContracts, the cases with no statements yet (testCasesWithoutStatements, with statementFormat) and the per-case summary (passed, failed, stale). Test budget: one binding test per criterion first; more per criterion is sprawl, and get_project_status\'s testBudget gauge flags it. Doctrine: docs/WORK_LOOP_PLAN.md Phase C5.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, requirement_id: { type: 'string', description: 'The requirement: its REQ-xxx id or its row UUID' } }, required: ['project_id', 'requirement_id'] }, requiredScope: 'read' },
  { name: 'report_test_results', description: 'Record the results of tests you actually ran for a requirement; the evidence lane. Upserts test cases keyed (requirement_id, test_id); passed and failed flip the linked criterion\'s met flag (skipped, running and not_started leave it), and a fresh result clears the case\'s staleness. Bind a case to its criterion with criterion_text, the criterion\'s EXACT wording: unmatched text comes back as unbound; a criterion bound to another case is never stolen (conflict); a verification: \'manual\' criterion is never bound (criterionBinding \'manual-lane\'; the task-doc tick and the user\'s approval prove it). Flipped criteria carry test provenance. Pass git: { commit_sha, branch } after you commit and push: the sha is stamped on every flipped criterion and the verified lease. The repository must have the commit: a sha it does not have is refused and nothing is recorded; a commit not yet on the tracked branch holds the passed and failed results (held), which count when the sync check sees it there. A counted passing result releases your own task leases on this requirement\'s nodes (checkoutsReleased, reason \'verified\'); failing-only reports hold them. The receipt: per-case outcomes, flippedCriteria (the post-write met state), and a testBudget nudge past one binding test per criterion. Never report a result you did not run. Doctrine: docs/WORK_LOOP_PLAN.md Phase C5. Proof, not declaration: mark_entity_complete and update_test_case flip nothing.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, requirement_id: { type: 'string', description: 'The requirement row UUID (or REQ-xxx id)' }, results: { type: 'array', items: { type: 'object', properties: { test_id: { type: 'string', description: 'Stable test key within the requirement (e.g. "TC-001" or file::test-name); the upsert key together with requirement_id' }, status: { type: 'string', enum: ['passed', 'failed', 'skipped', 'running', 'not_started'], description: 'The actual execution outcome. Only passed/failed flip criteria.' }, criterion_text: { type: 'string', description: 'EXACT text of the acceptance criterion this test verifies: binds the criterion to this case so the met-flip trigger can act. Copy it verbatim from list_requirements.' }, name: { type: 'string', description: 'Human-readable test name (defaults to test_id for new cases)' }, description: { type: 'string' }, test_type: { type: 'string', enum: ['unit', 'integration', 'e2e', 'acceptance', 'performance', 'security'] }, framework: { type: 'string', description: 'Test framework id (e.g. vitest, jest, pytest, playwright, go_test, rust_test, other)' }, artifact_path: { type: 'string', description: 'Repo path of the test file implementing this case' }, source_artifact_ids: { type: 'array', items: { type: 'string' }, description: 'Artifact UUIDs of the source files this test verifies (feeds the staleness triggers)' }, expected_result: { type: 'string' }, implementation: { type: 'string', description: 'The test code or a pointer to it' } }, required: ['test_id', 'status'] }, description: 'One entry per executed test case' }, external_agent: { type: 'string', description: 'Identifier for the reporting agent' }, git: { type: 'object', properties: { commit_sha: { type: 'string', description: 'Hex sha (7 to 64 chars) of a commit in the repository the evidence was produced at; commit and push before reporting' }, branch: { type: 'string', description: 'The branch that commit is on' } }, description: 'The commit this evidence belongs to (R8): stamped on every flipped criterion and on the verified lease' } }, required: ['project_id', 'requirement_id', 'results'] }, requiredScope: 'write' },
  { name: 'update_test_case', description: 'Maintain an EXISTING test case; reporting only upserts, this renames, reassigns, retires or re-binds. Cases are never hard-deleted. retire: true (retire_reason required) drops the case from every count surface but keeps the row; its criteria are released with met preserved and evidence marked stale; a fresh report for the same test_id revives it, retire: false un-retires it. reassign_to moves the case to another requirement in the same spec and marks it stale (\'Reassigned from REQ-xxx\') until it runs there. new_test_id, name and description rename it; a (requirement, test_id) collision is refused naming the holder. criterion_text re-binds by the criterion\'s EXACT text on the owning requirement: exact match only, a verification: \'manual\' criterion is refused, a criterion bound to a different case is never stolen, and binding alone never flips met; it cannot combine with retire: true. Doctrine: docs/WORK_LOOP_PLAN.md Phase C5. Maintenance of an existing case; to record a run and flip a criterion use report_test_results.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, requirement_id: { type: 'string', description: 'The requirement CURRENTLY owning the case (REQ-xxx or row UUID)' }, test_id: { type: 'string', description: 'The case\'s stable key within the requirement (e.g. "TC-001") — identifies which case to update' }, new_test_id: { type: 'string', description: 'Rename the case\'s test_id (refused when the target key is taken on the final owning requirement)' }, name: { type: 'string', description: 'New human-readable test name' }, description: { type: 'string', description: 'New description' }, retire: { type: 'boolean', description: 'true soft-retires the case (requires retire_reason; releases its criterion bindings); false un-retires it. Never a hard delete.' }, retire_reason: { type: 'string', description: 'Why the case is being retired (e.g. "superseded by TC-004") — required with retire: true' }, reassign_to: { type: 'string', description: 'Requirement (REQ-xxx or row UUID) to move the case to — the case arrives deliberately stale and must be re-run there' }, criterion_text: { type: 'string', description: 'EXACT text of the acceptance criterion on the final owning requirement to bind this case to (the reword-recovery lane). Binding never flips met.' } }, required: ['project_id', 'requirement_id', 'test_id'] }, requiredScope: 'write' },
  { name: 'list_requirements', description: 'List all requirements for a project specification, enriched with spec-plane context. Per requirement: id/name/category/status/acceptance criteria/locked, plus sectionId+sectionName, confirmed, architectureTrace, mappedNodeIds, authored relations ({from: outgoing, to: incoming} — expands/depends_on/relates_to rows written via relate_requirements or create_requirement), inPlay/heldBy (an agent currently holds a task on one of its mapped nodes — the lighter in-play marker, derived from active checkouts at read time), and DERIVED coupling: other requirements that share a mapped node (kind \'shared_node\', via = the node label) or whose mapped nodes are bridged by a graph edge (kind \'adjacent\', via = "Source → Target"). Coupling is computed at read time from the main-branch graph and never stored — use it to answer "what else does this change touch?", and record intent (lineage, ordering) with relate_requirements. Use after get_project_status to inspect the full specification, or before update_requirement / delete_requirement. Supports filtering by category or status (relations and coupling then cover only the returned rows).', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, category: { type: 'string', description: 'Optional filter by requirement category (e.g., functional, non-functional, technical)' }, status: { type: 'string', description: 'Optional filter by requirement status (e.g., pending, implemented)' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'mark_entity_complete', description: 'Declare a node\'s implementation COMPLETE (or revert the declaration). Writes validation_status=\'valid\' + provenance on the node\'s requirement mappings: the per-node implementation badge in the Spec view. THIS TOOL NEVER FLIPS ACCEPTANCE CRITERIA: \'the component is done\' is a declaration; \'this criterion is proven\' requires evidence. Criteria flip only via report-test-results evidence or by ticking the criterion box in the node\'s task doc and having the user approve the resulting change card. The response lists any still-unmet criteria so you know what proof is outstanding. Accepts a node UUID, an exact node label, or a task-artifact id (resolves to its owning node). A declaration, not proof: only report_test_results flips a criterion, with evidence.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, node_id: { type: 'string', description: 'Node UUID, exact node label, or task-artifact id' }, branch_id: { type: 'string', description: 'Optional branch UUID to resolve the entity against. Defaults to the primary branch.' }, complete: { type: 'boolean', description: 'Default true. false reverts the declaration to pending (criteria untouched either way).' }, note: { type: 'string', description: 'Optional short note recorded in the provenance (e.g. what was delivered).' }, external_agent: { type: 'string', description: 'Identifier for the declaring agent (recorded as provenance actor)' } }, required: ['project_id', 'node_id'] }, requiredScope: 'write' },
  { name: 'map_requirement', description: 'Manage which architecture nodes a requirement maps to (requirement traceability: how AI-built architecture shows up on a requirement record under Work). Three modes: "add" (default) unions the given nodes into the existing mappings; "remove" deletes the given node links: the ONLY lane for pruning stale mappings that reference deleted nodes, so it deliberately accepts node ids that are no longer in the graph; "replace" makes the given list the exact mapping set (anything else, including dangling links, is removed). For add/replace, node_ids must be UUIDs of nodes present in the target branch graph (defaults to main); call get_architecture_overview for valid ids. Every mode dual-writes the specification_mappings rows and the requirement architecture trace. AUTONOMY ROUTING: this tool consults the project\'s per-lane automation policy: at \'Ask first\' the call is refused (discuss with the user); at \'Propose\' nothing is changed and the call files a pending proposal instead (response carries routed: proposed + proposalId; the user accepts in the approvals queue or via resolve_proposal); at \'Auto-apply\' (the shipped default, today\'s behavior) it applies and records a merged proposal row as audit. Binds a requirement to NODES; requirement-to-requirement lineage is relate_requirements.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, requirement_id: { type: 'string', description: 'Requirement id (REQ-xxx) or row UUID' }, node_ids: { type: 'array', items: { type: 'string' }, description: 'Node UUIDs to add, remove, or set (per mode). Empty is allowed only with mode "replace" (clears all mappings).' }, mode: { type: 'string', enum: ['add', 'remove', 'replace'], description: "Defaults to 'add'." }, branch_id: { type: 'string', description: 'Optional branch UUID to validate node ids against (add/replace). Defaults to the main branch (which the traceability view reads).' }, mapping_type: { type: 'string', enum: ['implements', 'depends_on', 'validates', 'supports'], description: "Relationship type for newly created links. Defaults to 'implements'." } }, required: ['project_id', 'requirement_id', 'node_ids'] }, requiredScope: 'write' },

  { name: 'get_work_queue', description: 'The next unblocked implementation tasks, in the pinned order: the ACCEPTED work plan when one exists, else the deterministic fallback — the same dependency-ordered buildOrder get_build_readiness computes (contract upstream + container parent), then the task doc\'s order within a node. Entries are the task docs\' work orders that are not done or orphaned: taskItemId (what checkout_task claims; null until someone ticks or claims it, so claim by node_id + task_key), the task key (the <!-- t:key --> anchor), title, owning node, and heldBy/holderSince/holdStale when held. Held work stays in the queue: a checkout is advisory, and a hold silent 30 minutes is claimable. At the top of a work loop: read this, checkout_task, build per the node task doc, prove via report_test_results, release. COLLISION BOARD: activeHolds lists EVERY active lease in the project at every level (task/code exclusive, requirement/outcome advisory drafting holds), each with holder, credential (the key name or OAuth client behind it), target label, since, stale, credentialExpiresAt (when that credential stops working; null = never/unknown), and mine (true for the calling credential\'s own holds, an OAuth connector across token renewals). Read it before touching held work: do not edit a requirement or outcome another agent holds a fresh drafting lease on; coordinate through proposals; a stale hold is fair game. This is WHAT TO DO NEXT; the ordering artifact itself (layers, critical path) is get_work_plan.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID for the dependency ordering. Defaults to the primary branch.' }, limit: { type: 'number', description: 'Max entries (default 20, cap 100)' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'get_work_plan', description: "The work plan: what to do next and why (the server half of the app's Plan tab, under Work). Returns the ACCEPTED plan for the branch when one exists (stale:true when the task docs or tests changed since it was proposed) and ALWAYS the deterministic graph: every implementation task (from the task docs, with task_items state) and every test case as an item; the classified edges between them (TIGHT is hard precedence the plan may not invert (a node's own doc order, a declared coupling, a contract whose downstream side has a test, a test after its node's work), LOOSE is advisory (a contract nothing tests yet, repo-index dependencies, a shared requirement or technology)); layers; the effort-weighted critical path (1 per task, 0.5 per test) with slack per item; and openQuestions, the tight cycles the engine refuses to guess. source is 'accepted-plan' or 'deterministic'. Workflow: read this, then propose_work_plan your order with a rationale per item; the user accepts. TIER: Indie and above; a Community account gets a named refusal; get_work_queue's build-order fallback stays available everywhere.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID (defaults to the primary branch)' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'propose_work_plan', description: "Propose the order of operations over get_work_plan's graph. items is the FULL order: every graph item exactly once, by the ids get_work_plan returned (task:<node>:<key>, test:<req>:<testId>), each with an optional effort estimate and a one-line rationale; summary says what the order optimizes for; decisions answer the open questions (a decision on one edge of each tight cycle). Validated BEFORE anything is written: a tight inversion, a missing / duplicate / unknown item or an unanswered cycle refuses the whole proposal by name (data.problems). Writes a new 'proposed' plan version (rank is your order; layer, effort, earliest start, slack and the critical flag come from the engine with your estimates) and returns the diff against the accepted plan (added, removed, moved). Nothing changes for get_work_queue until the plan is accepted: by the user, or as it files when the Tasks lane is at Auto and you act for the owner with write access. TIER: Indie and above.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID (defaults to the primary branch)' }, items: { type: 'array', items: { type: 'object', properties: { id: { type: 'string', description: 'An item id from get_work_plan (task:<node>:<key> or test:<req>:<testId>)' }, effort: { type: 'number', description: 'Your estimate (default 1 per task, 0.5 per test)' }, rationale: { type: 'string', description: 'One line: why here' } }, required: ['id'] }, description: 'The complete proposed order' }, summary: { type: 'string', description: 'What this order optimizes for' }, decisions: { type: 'array', items: { type: 'object', properties: { from: { type: 'string' }, to: { type: 'string' }, decision: { type: 'string' } }, required: ['from', 'to', 'decision'] }, description: 'One decision per open question, on an edge of the cycle' } }, required: ['project_id', 'items', 'summary'] }, requiredScope: 'propose' },
  { name: 'accept_work_plan', description: "Accept a proposed work plan (plan_id from propose_work_plan): the user's last word, also reachable from the Plan tab in the app; call it only when the user has told you to. Refused when the plan is stale (the task docs or tests changed since it was proposed; read get_work_plan and propose again) or not 'proposed'. Supersedes the branch's previous accepted plan; from then on get_work_queue serves this order (source 'accepted-plan'). TIER: Indie and above.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, plan_id: { type: 'string', description: 'The proposed plan UUID' } }, required: ['project_id', 'plan_id'] }, requiredScope: 'write' },
  { name: 'list_project_members', description: "Who is on a project (Team, 7.0): the owner and every seat with its role — maintainer | contributor | viewer — plus your own seat (yourRole). Any member reads it (each seat with its clearance — the classification marks it may see). Seats decide what a tool may do: read tools need viewer, propose and write tools need contributor; accepting plans and resolving proposals is the owner's on any channel and a maintainer's in the app only — a member's agent never approves.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'set_project_member', description: "Grant, change or remove a seat on a project by the account's email — the project owner only, and only when the user tells you to. Roles: maintainer (edits, approves in the app, updates the project row), contributor (edits and proposes), viewer (reads); 'remove' takes the seat away. Ownership is the project row, never a seat — no tool transfers it. The invitee must already have an account on this deployment. TIER: Team and above.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, email: { type: 'string', description: "The invitee's NodeSpec account email" }, role: { type: 'string', enum: ['maintainer', 'contributor', 'viewer', 'remove'], description: 'The seat to grant, or remove' }, clearance: { type: 'array', items: { type: 'string' }, description: "7.3 (Government): the marks this seat may see, exactly (e.g. ['CUI', 'CUI//SP-PRVCY']); omitted keeps the current clearance, [] clears it" } }, required: ['project_id', 'email', 'role'] }, requiredScope: 'write' },
  { name: 'get_outcome_board', description: 'The OUTCOMES pool an agent reads before suggesting a derivation: every pending outcome on the branch (prompt data — what a workflow should achieve) with its draft criteria AND THEIR IDS (what promote_candidate\'s criteriaIds claims), claimedBy per criterion (already derived into REQ-nnn), unclaimedCriteriaIds, the workflow steps it maps to, what it already derived (derivations with requirementId + criteriaIds), the advisory holds on it (holder, credential, mine, stale), the vision sentences with their ids (vision.sentences) and what each outcome serves (serves; current false is a sentence the vision no longer has). User-authored text arrives in the untrusted-data envelope. Every board carries workflows.available; below Indie it is false and lanes, homeLane and steps are OMITTED, not empty. THE LANE: checkout_task {level: outcome, ref_id: candidateId} (advisory — coexists with other agents) → propose_patches with one promote_candidate per requirement ({ candidateId, criteriaIds, name }) guarded by hash_match on criteria[id=<id>].text, or attach_candidate ({ candidateId, requirementId }) to derive against a requirement that already exists (nothing minted; a locked one refuses) → the user accepts in the app (promote and settle are never accepted over a key or OAuth token) → your hold binds to the proposal on filing and releases as resolved when the user decides. Agents draft below the promotion line; a human crosses it.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, branch_id: { type: 'string', description: 'Optional branch UUID. Defaults to the primary branch.' }, include_settled: { type: 'boolean', description: 'Also list settled (accepted) outcomes. Default false — pending only.' } }, required: ['project_id'] }, requiredScope: 'read' },
  { name: 'checkout_task', description: 'Claim work: the lease that tells the board and other agents who works what. NODE (level node, node_id) is a lock: the node\'s structure (role, technology, configuration, edges, contracts, bound files, task document) changes only through its holder; it waits while others work inside the node, and blocks new work there while held. TASK and CODE are exclusive per ref and run in parallel inside a node: your reach is the files in touches, their imports inside the node and what the same tests verify (none named: the whole node); a refusal names the holder, what it holds and the file coupling you. CRITERION (ref_id = requirement row UUID, criterion_id) is exclusive: one criterion, one binding test. REQUIREMENT and OUTCOME are advisory drafting holds tied to a pending proposal (proposal_id). A fresh hold returns claimed:false with the holder (render it, work something else); a hold silent 30 minutes is reclaimed, the old lease kept as audit. The response carries your reach and handoff, the note the last holder left. Task refs: task_item_id from get_work_queue, or node_id + task_key (a work order the node\'s task doc lists; the claim records its row). A work order that is done, ticked in its doc with no row, or orphaned is refused. Leases never gate evidence: report_test_results and task ticks work lease-less. Keep it fresh with checkout_heartbeat; end it with release_checkout, verified evidence, or staleness.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, level: { type: 'string', enum: ['task', 'code', 'requirement', 'outcome', 'criterion', 'node'], description: "Defaults to 'task'. node locks a node's structure (node_id)." }, task_item_id: { type: 'string', description: 'Task item UUID from get_work_queue (level task)' }, node_id: { type: 'string', description: 'Owning node UUID: with task_key, the alternative task ref; alone, the node a node lease locks' }, touches: { type: 'array', items: { type: 'string' }, description: 'Levels task and code: the repository paths this work will touch. Your reach is these, their imports inside the node, and what the same tests verify; none named reaches the whole node.' }, task_key: { type: 'string', description: 'The task anchor key (hex8 from <!-- t:key -->)' }, ref_id: { type: 'string', description: 'Ref UUID for levels code (artifact), requirement, outcome (candidate), criterion (the requirement ROW uuid)' }, criterion_id: { type: 'string', description: "Level criterion only: WHICH criterion in that requirement — its v3l id (e.g. 'ab12cd34' or 'h1f2e3d4'), never the text" }, branch_id: { type: 'string', description: 'Optional branch UUID (recorded on branch-scoped holds)' }, proposal_id: { type: 'string', description: 'The pending proposal an advisory requirement/outcome hold drafts for' }, external_agent: { type: 'string', description: 'Identifier shown as the holder (e.g. "claude · test-runner")' }, meta: { type: 'object', description: 'Display state: { tests: [...], touches: [...] }' } }, required: ['project_id'] }, requiredScope: 'write' },
  { name: 'checkout_heartbeat', description: 'Keep your own held lease fresh and update its progress display state (meta: tests running, files touched — what the board renders under the holder). A lease silent for 30 minutes reads stale-held and becomes claimable by others, so heartbeat between work steps. If the response says the checkout is gone (released or reclaimed), re-claim via checkout_task before continuing — do not keep working a lease you lost. meta may carry commitSha — the commit you are working at (the board renders it as @sha7); the verified exit keeps it beside meta.verified. AA.5: meta.touches lists the files you touched; one outside your reach extends the lease when no one else\'s work reaches it, and comes back in outsideScope (with its holder) when someone\'s does.', inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, checkout_id: { type: 'string', description: 'The checkout UUID from checkout_task' }, meta: { type: 'object', description: 'Merged into the lease\'s display state: { tests: [...], touches: [...], commitSha?: string }' } }, required: ['project_id', 'checkout_id'] }, requiredScope: 'write' },
  { name: 'release_checkout', description: "End a lease with an audited reason: 'released' (default — stepping away, work incomplete; on an exclusive lease it needs a note saying where the work stands, and the next claim on it receives that note), 'verified' (the work was proven — you reported the results via report_test_results first), or 'resolved' (an advisory requirement/outcome hold whose proposal settled). Released rows are never deleted — they are the audit trail of who held what. Releasing does not mark anything done: completion is evidence (report_test_results) or a task-doc tick, never a lease state.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, checkout_id: { type: 'string', description: 'The checkout UUID from checkout_task' }, reason: { type: 'string', enum: ['released', 'verified', 'resolved'], description: "Defaults to 'released'." }, note: { type: 'string', description: "Required when the project owner or a maintainer releases a lease someone else holds: why. Recorded on the lease. Only the holder releases its own lease otherwise." } }, required: ['project_id', 'checkout_id'] }, requiredScope: 'write' },
  { name: 'resolve_proposal', description: "Accept or reject a PENDING spec-plane proposal (requirement / outcome / workflow kinds): the server half of the approvals queue. Reject also closes a partial proposal (what applied stays applied) and works on either plane. Promotion and settle (promote_candidate / settle_candidate) are accepted ONLY by the signed-in user's session (R7): an API key or OAuth token is a delegate and cannot approve what it proposed; the derivation records the proposal as its origin. Accept applies each patch through the lane a direct edit uses (locks refuse, decided candidates are terminal), then marks it merged; it is NOT transactional: a mid-batch refusal leaves it 'partial' with per-patch statuses, never a silent half-merge. Graph-patch proposals are never accepted here (the canvas decides them, or Auto does), and a promotion never over MCP: the user accepts it in the app under Agents, Proposals, the header's one approvals door (R17), which posts this same tool with the user's session. Reject marks every patch rejected with your note. action 'auto' (no proposal_id) applies what the Auto lanes cover among the waiting proposals, on either plane, and at Tasks Auto the newest proposed plan per branch; what still waits is listed with its reason. A proposal is something an agent asked for, never a git commit: an inbound change card is decided with resolve_change.", inputSchema: { type: 'object', properties: { project_id: { type: 'string', description: 'The project name or UUID' }, proposal_id: { type: 'string', description: 'The pending proposal UUID (from a routed: proposed response, or get_proposal_status); not used with action auto' }, action: { type: 'string', enum: ['accept', 'reject', 'auto'], description: 'accept applies and merges; reject settles it; auto applies what the Auto lanes cover among the waiting proposals' }, note: { type: 'string', description: 'Optional reviewer note recorded on the resolution' } }, required: ['project_id', 'action'] }, requiredScope: 'write' },
];

/** R19: the nearest real tool names to a mistyped one. The unknown-tool
 *  refusal derives its suggestions here instead of a hand-kept list (the
 *  old literal had drifted to 19 of 44 names and taught connected agents
 *  that the V3 lanes did not exist). Pure — this module stays importable
 *  by the test suite: data plus this function, zero imports. `names`
 *  narrows the candidates (Q: a plan's own list, tool-surface.ts). */
export function nearestToolNames(input: string, max = 3, names: readonly string[] = MCP_TOOLS.map((t) => t.name)): string[] {
  const dist = (a: string, b: string): number => {
    const n = b.length;
    const row = Array.from({ length: n + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      let prev = row[0];
      row[0] = i;
      for (let j = 1; j <= n; j++) {
        const tmp = row[j];
        row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
        prev = tmp;
      }
    }
    return row[n];
  };
  const q = String(input ?? "").toLowerCase().trim();
  if (!q) return [];
  return names
    .map((name) => ({ name, d: dist(q, name) }))
    .filter((x) => x.d <= Math.max(3, Math.floor(q.length / 3)))
    .sort((a, b) => a.d - b.d || a.name.localeCompare(b.name))
    .slice(0, max)
    .map((x) => x.name);
}
